def frequency_rank_map(items):
    c = {}
    first_idx = {}
    for i, x in enumerate(items):
        if x not in c:
            first_idx[x] = i
        c[x] = c.get(x, 0) + 1
    uniq = sorted(c.keys(), key=lambda x: (-c[x], first_idx[x]))
    return {x: i + 1 for i, x in enumerate(uniq)}

